def apply_ops(ops):
    stock = {}
    undo_stack = []
    for op in ops:
        if op[0] == 'undo':
            if undo_stack:
                stock = undo_stack.pop()
        else:
            item, qty = op[1], op[2]
            stock[item] = stock.get(item, 0) + qty
            undo_stack.append(stock.copy())
    return stock
```

```python
def count_sum_increases(readings, k):
    if k <= 0 or len(readings) < 2 * k:
        return 0
    s = sum(readings[:k])
    count = 0
    for i in range(k, len(readings) - k + 1):
        s += readings[i] - readings[i - k]
        if s > sum(readings[i - k:i]):
            count += 1
    return count
```

