def most_frequent_digit(counts):
    if not counts:
        return None
    counts = [str(c) for c in counts]
    freq = {}
    for c in counts:
        for ch in c:
            freq[ch] = freq.get(ch, 0) + 1
    return max(freq, key=freq.get)
```

