```python
def valid_palindrome_one_deletion(s):
    def is_pal(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True
    for i in range(len(s)):
        if is_pal(0, i - 1) and is_pal(i + 1, len(s) - 1):
            return True
    return False
```

```python
def eval_postfix_digits(expr):
    ops = {'+': lambda a, b: a + b, '-': lambda a, b: a - b, '*': lambda a, b: a * b, '/': lambda a, b: a // b}
    stack = []
    for ch in expr:
        if ch in ops:
            b, a = stack.pop(), stack.pop()
            stack.append(ops[ch](a, b))
        else:
            stack.append(int(ch))
    return stack[0]
```

